const FIELD_ANGGARAN_MP = new Set(['pagu_mp_1', 'realisasi_mp_1', 'pagu_mp_2', 'realisasi_mp_2', 'pagu_mp_3', 'realisasi_mp_3', 'pagu_mp_4', 'realisasi_mp_4', 'pagu_mp_5', 'realisasi_mp_5'])
